  p('그는 끝내 자신의 신념을 굽히지 않았다.','彼はついに自分の信念を曲げなかった。','ついに·曲げる'),
  p('이번 일을 거울삼아 같은 실수를 피하려 한다.','今回のことを教訓にして、同じ過ちを避けたい。','教訓·避ける'),
  p('현실적인 목표 설정이 동기 부여로 이어진다.','現実的な目標設定が、やる気につながる。','につながる·やる気'),
  p('그 결과는 노력의 산물이라고 보아도 무방하다.','その結果は、努力の賜物と見て差し支えない。','差し支えない·賜物'),
  p('어떤 일이든 균형 감각이 무엇보다 중요하다.','どんなことでも、バランス感覚が何より大切だ。','でも·バランス'),
  p('이 정도 위험은 충분히 관리할 수 있는 수준이다.','この程度のリスクは、十分に管理できる水準だ。','水準·管理'),
  p('상황이 어렵다고 해서 기준을 낮출 수는 없다.','状況が厳しいからといって、基準を下げるわけにはいかない。','からといって·わけにはいかない'),
  p('그는 위기 앞에서도 침착함을 잃지 않았다.','彼は危機を前にしても、落ち着きを失わなかった。','を前にして·失う'),
  p('이번 결과를 바탕으로 개선안을 마련하겠다.','今回の結果を踏まえて、改善案をまとめる。','を踏まえて·改善案'),
  p('현실을 모른 채 내린 판단은 위험하기 짝이 없다.','現実を知らないまま下した判断は、危険極まりない。','まま·極まりない'),
  p('아무리 노력해도 운이 따르지 않을 때가 있다.','どんなに努力しても、運が味方しないときがある。','ても·味方'),
  p('그 제안은 신중하게 검토할 가치가 충분하다.','その提案は、慎重に検討する価値が十分にある。','価値·十分'),
  p('비판과 비난을 혼동해서는 안 된다.','批判と非難を混同してはならない。','混同·てはならない'),
  p('어떤 선택을 하든 그에 따른 책임이 따른다.','どんな選択をしても、それに伴う責任が生じる。','に伴う·生じる'),
  p('이 결과는 우리가 나아갈 방향을 시사한다.','この結果は、私たちが進むべき方向を示唆している。','示唆·べき'),
  p('현실적인 대책 없이 구호만 외쳐서는 안 된다.','現実的な対策なしに、スローガンばかり叫んではならない。','なしに·ばかり'),
  p('그는 모든 가능성을 열어 두고 신중히 접근했다.','彼はあらゆる可能性を残して、慎重に取り組んだ。','残す·取り組む'),
  p('이번 경험을 통해 한 단계 성장한 느낌이다.','今回の経験を通じて、一段階成長した気がする。','を通じて·気がする')
